const eq=checkEquation(q);if(eq){if(eq.proposed===null)return{kind:'EQUATION_CHECK_NEEDS_ATTEMPT',summary:'I can check this equation once you share your value for x or your steps.',workedProcess:[`Equation detected: ${eq.equation}.`,'To check your reasoning, I need your proposed value or the step where you are unsure.','A good self-check is to substitute your value back into the original equation.'],keyTerms:['equation','substitution','solution'],confidence:'Insufficient Information',confidenceReason:'The equation is present, but the student’s attempted answer is missing.'};return{kind:'EQUATION_CHECK',summary:eq.correct?`Your value x = ${eq.proposed} checks correctly.`:`x = ${eq.proposed} does not satisfy the equation; recheck the inverse operations.`,workedProcess:[`Original equation: ${eq.equation}.`,`Substitute x = ${eq.proposed}: left side becomes ${Number((Number(eq.proposed)*Number(q.replace(/\s+/g,'').match(/(-?\d*)x/i)?.[1]||1))+Number(q.replace(/\s+/g,'').match(/x([+-]\d+)/i)?.[1]||0)).toPrecision(6)}.`,'Compare the left side with the right side.','If they match, the solution is correct; if not, find the first inverse-operation mistake.'],keyTerms:['equation','substitution','solution'],confidence:'High',confidenceReason:'The proposed value was checked by substitution.'}}
if(/mean|median|dataset|data set/i.test(q)){const nums=parseNumbers(q);if(nums.length>=2){const sum=nums.reduce((a,b)=>a+b,0),mean=sum/nums.length,med=median(nums);return{kind:'STATISTICS',summary:`Mean: ${Number(mean.toPrecision(5))}; median: ${Number(med.toPrecision(5))}.`,workedProcess:[`Known values: ${nums.join(', ')}.`,'Required value: mean and median.','Formula or relationship: mean = sum ÷ count; median = middle value after ordering.',`Substitution: sum = ${sum}; count = ${nums.length}; mean = ${Number(mean.toPrecision(5))}.`,`Ordered data: ${[...nums].sort((a,b)=>a-b).join(', ')}; median = ${Number(med.toPrecision(5))}.`,'Reasonableness check: the mean and median should sit near the centre of the dataset unless there is an outlier.'],keyTerms:['mean','median','dataset'],confidence:'High',confidenceReason:'The values were calculated directly from the numbers in the question.'}}}
