function extractVocabularyTerm(question){const q=clean(question);const patterns=[/define\s+(?:the\s+)?(?:word\s+|term\s+)?["“]?([^"”?.]+)["”]?/i,/explain\s+([A-Za-z][A-Za-z -]{2,40})\s+in\s+English/i,/word family for\s+([A-Za-z][A-Za-z -]{2,40})/i,/flashcard for\s+([A-Za-z][A-Za-z -]{2,40})/i,/translate\s+(?:the\s+)?(?:term\s+)?["“]?([^"”?.]+)["”]?/i];for(const pattern of patterns){const hit=q.match(pattern)?.[1];if(hit)return clean(hit).replace(/\s+(?:in|and|with)\s+.*$/i,'')}const entry=(LIB?.VOCABULARY_ENTRIES||[]).find(x=>new RegExp(`\\b${x.term}\\b`,'i').test(q));return entry?.term||null}
