function toolResultFor(question,route,context){try{if(route.subject==='VOCABULARY'||/define|translate|word family|flashcard|key words/i.test(question))return vocabularySupport(question,context);const checks=[];if(route.subject==='MATH'||(route.subject==='MULTI_SUBJECT'&&route.candidateSubjects?.includes('MATH')))checks.push(()=>mathTool(question,route.mode));if(route.subject==='PHYSICS'||(route.subject==='MULTI_SUBJECT'&&route.candidateSubjects?.includes('PHYSICS')))checks.push(()=>physicsTool(question));if(route.subject==='CHEMISTRY'||(route.subject==='MULTI_SUBJECT'&&route.candidateSubjects?.includes('CHEMISTRY')))checks.push(()=>chemistryTool(question));for(const run of checks){const result=run();if(result)return result}return null}catch(error){return{kind:'TOOL_ERROR',summary:TOOL_FAILURE,workedProcess:[clean(error?.message)||TOOL_FAILURE],keyTerms:[],confidence:'Insufficient Information',confidenceReason:'The deterministic tool could not safely complete the check.'}}}
