const processLimit=responseDetailLevel(detail)==='DETAILED'?7:(toolResult?7:4);
let answer=limitText(generated.explanation||generated.summary||UNSUPPORTED_TOPIC,detail),comparison=comparisonFor(question,route),worked=Array.isArray(generated.workedProcess)?generated.workedProcess.slice(0,processLimit):[],example=comparison||toolResult?null:usefulExample(generated,route,detail),keyTerms=null,answerLabel='Direct Answer',showTrust=true;
if(modeCode(route.mode)==='GIVE_ME_A_HINT'){answerLabel='Hint';worked=[];comparison=null;example=null}
