function getCoachAcademicContextFromDOM(extra={}){if(typeof document==='undefined')return extra;const select=id=>document.getElementById(id)?.value||'';const selected=select('coachSubjectSelect');const course=select('coachCourseLevelSelect')||select('coachCourseSelect');const topic=document.getElementById('coachTopicInput')?.value||'';const mode=select('learningModeSelector')||select('coachHelpTypeSelect'),responseDetail=select('coachResponseDetailSelect')||extra.responseDetail||'STANDARD';let bridgeLanguageCode=null;try{bridgeLanguageCode=root.LanguageBridge?.getBridgePreferences?.()?.homeLanguageCode||null}catch(_){bridgeLanguageCode=null}return{...extra,selectedSubject:selected||'AUTO',courseLevel:course||extra.courseLevel||extra.currentCourse||'',topic,learningMode:mode||extra.learningMode||'COACH_ME',responseDetail,bridgeLanguageCode,selectedCourses:extra.selectedCourses||[]}}
