function bindQuickStarts(form){const input=form.querySelector('#coachInput'),status=document.getElementById('coachComposerStatus'),subjectSelect=form.querySelector('#coachSubjectSelect'),examples=form.querySelector('.coach-subject-examples');form.querySelectorAll('[data-coach-subject-quickstart]').forEach(button=>{button.addEventListener('click',()=>{const code=button.dataset.coachSubjectQuickstart;if(subjectSelect)subjectSelect.value=code;const prompts=SUBJECT_QUICK_STARTS[code]||[];examples.innerHTML=prompts.map(prompt=>`<button type="button" data-coach-example-prompt="${esc(prompt)}">${esc(prompt)}</button>`).join('');examples.querySelectorAll('[data-coach-example-prompt]').forEach(example=>example.addEventListener('click',()=>{if(input&&!input.value.trim())input.value=example.dataset.coachExamplePrompt;else if(input)input.value=`${input.value.trim()} ${example.dataset.coachExamplePrompt}`.trim();input?.dispatchEvent(new Event('input',{bubbles:true}));if(status)status.textContent='Example question added. Edit it if you want, then press Send.';input?.focus()}));if(status)status.textContent=`${button.textContent.trim()} context selected. Example questions are available below.`;input?.focus()})})}
