function createFlashcard(term){const card=vocabularyCard(term,{})||{term,plainDefinition:'Review this academic term.',subject:'Vocabulary'};try{const u=typeof root.user==='function'?root.user():null;if(u?.flashcards){u.flashcards.push({id:`vocab-card-${Date.now()}`,subject:card.subject||'Vocabulary',question:`What does ${card.term} mean?`,answer:card.plainDefinition,topic:card.term});if(typeof root.saveDB==='function')root.saveDB();return{created:true,message:`Flashcard created for ${card.term}.`}}}catch(_){}return saveToInternalVocabulary(term).saved?{created:true,message:`${card.term} was saved. Open flashcards to practise it.`}:{created:false,message:`${card.term} is already saved for vocabulary practice.`}}
function actionText(action,term){const card=vocabularyCard(term,{})||{};if(action==='Define This Word')return card.plainDefinition||`Add context so StudySpark can define ${term}.`;if(action==='Translate This Term')return card.translations?.['zh-Hans']?`${card.term}: ${card.translations['zh-Hans']} (Simplified Chinese). English term preserved: ${card.term}.`:'A verified translation is not available yet.';if(action==='Use It in a Sentence')return card.exampleSentence||`Write your own course sentence using ${term}.`;if(action==='Show Related Terms')return card.relatedTerms?.length?`Related terms: ${card.relatedTerms.join(', ')}.`:'No approved related terms are available yet.';if(action==='Quiz Me')return`Quick quiz: Use ${term} in a sentence from your current subject, then explain why it fits.`;return''}
function bindAcademicResponseActions(scope=document){if(typeof document==='undefined')return;scope.querySelectorAll?.('[data-academic-trust-toggle]')?.forEach(button=>{if(button.dataset.boundAcademicTrustToggle==='true')return;button.dataset.boundAcademicTrustToggle='true';button.addEventListener('click',()=>{const panel=document.getElementById(button.getAttribute('aria-controls')||'');const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));if(panel)panel.hidden=expanded})});scope.querySelectorAll?.('[data-academic-vocab-action]')?.forEach(button=>{if(button.dataset.boundAcademicVocabAction==='true')return;button.dataset.boundAcademicVocabAction='true';button.addEventListener('click',()=>{const action=button.dataset.academicVocabAction,term=button.dataset.academicVocabTerm,status=button.closest('.academic-vocab-actions')?.querySelector('.academic-vocab-action-status');let result;if(action==='Add to My Vocabulary List')result=saveToInternalVocabulary(term).message;else if(action==='Create a Flashcard')result=createFlashcard(term).message;else result=actionText(action,term);if(status)status.textContent=result||'Action completed.'})})}
